// Percorre todos os itens que chegam ao nó
for (const item of $input.all()) {

  // Math.random() gera um número entre 0 (inclusivo) e 1 (exclusivo)
  const probabilidade = Math.random();

  // Se o número for menor que 0.30 (30% de chance), o resultado é 1.
  // Caso contrário (70% de chance), o resultado é 2.
  if (probabilidade < 0.30) {
    item.json.resultado = 1;
  } else {
    item.json.resultado = 2;
  }
}

// Retorna os itens atualizados para o próximo nó
return $input.all();

assignments.value:
={{ $('Consultar - EVENTO').item.json.event_days.map(d => {
  const start = new Date(d.start);
  const end = new Date(d.end);
  const data = start.toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });
  const horaInicio = start.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit', timeZone: 'America/Sao_Paulo' });
  const horaFim = end.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit', timeZone: 'America/Sao_Paulo' });
  return `${data} das ${horaInicio} às ${horaFim}`;
}).join(' e ') }}

